6	/** Is `frame` inside one of these confirmed (or still-open) corner_swap spans?
7	 * `end_frame == null` means the span is still open — treated as running to
8	 * the end of the video. Shared by FighterOverlay (box/skeleton colour) and
9	 * describeEvent (fighter-name reconstruction) so both apply the same
10	 * correction to the same stretch of frames. */
11	export function isFrameSwapped(frame: number, spans: CornerSwapSpan[]): boolean {
12	  return spans.some(s => frame >= s.frame && (s.end_frame == null || frame <= s.end_frame));
13	}
